import{_ as t,o as n,c as a,ah as o}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Following your training","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apprenant/formation.md","filePath":"src/en/guide/apprenant/formation.md"}'),r={name:"en/guide/apprenant/formation.md"};function i(s,e,d,h,c,l){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="following-your-training" tabindex="-1">Following your training <a class="header-anchor" href="#following-your-training" aria-label="Permalink to &quot;Following your training&quot;">​</a></h1><p>Once your first instalment is paid, you move from administration to the training itself, which takes place in <strong>Sève</strong>. Kura keeps tracking your attendance and results.</p><h2 id="opening-your-access-to-seve" tabindex="-1">Opening your access to Sève <a class="header-anchor" href="#opening-your-access-to-seve" aria-label="Permalink to &quot;Opening your access to Sève&quot;">​</a></h2><p>Your Sève account opens <strong>automatically when the first instalment is paid</strong>. If a company funds part of your training, <strong>both shares</strong> of this first instalment must be paid.</p><p>You are enrolled in your cohort&#39;s course and you receive your <strong>welcome booklet</strong> (<code>LA-NB-YYYY-XXX</code>): by e-mail, then in <strong>My enrolment</strong> and <strong>My documents</strong>. It presents your training and, by name, the cohort&#39;s team with their e-mail addresses. A change of cohort produces a new one; the old one is kept.</p><p>To sign in to Sève, use your <strong>NextBoxx account</strong>: Sève relies on Kura to identify you, there is no second password to remember.</p><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to &quot;Attendance&quot;">​</a></h2><ul><li><strong>Virtual classes.</strong> Your attendance is read in Sève and flows back into Kura every hour. It cannot be edited in Kura; in case of discrepancy, the virtual class log prevails.</li><li><strong>In-person classes.</strong> The cohort&#39;s Lead Trainer records the attendance of each in-person or hybrid learner after the session. They can correct it afterwards.</li></ul><p>A <strong>late arrival counts as present</strong>; an <strong>excused absence counts as absent</strong>.</p><p>Your absence rate is the time of missed sessions relative to the training&#39;s hours (500 h, 700 h for Web &amp; Mobile Development, or 250 h). When it exceeds <strong>30%</strong>, you are notified, as are the Pedagogical Coordinators, once only: a correction bringing you back under the threshold rearms the alert.</p><h2 id="grades-and-blocks" tabindex="-1">Grades and blocks <a class="header-anchor" href="#grades-and-blocks" aria-label="Permalink to &quot;Grades and blocks&quot;">​</a></h2><p>The training is divided into <strong>skill blocks</strong>, each graded out of 20 in Sève. Grades flow back into Kura every hour.</p><table tabindex="0"><thead><tr><th>Block grade</th><th>Effect</th></tr></thead><tbody><tr><td>10/20 or more</td><td>Block validated</td></tr><tr><td>From 8 to under 10</td><td>Not validated, but compensable by the average</td></tr><tr><td>Under 8</td><td>Eliminatory</td></tr></tbody></table><p>Your <strong>average</strong> is weighted by the duration of each block, in weeks. It is recalculated at each reading. If a block was attempted several times, the grade kept is that of the last graded attempt.</p><h3 id="the-retake" tabindex="-1">The retake <a class="header-anchor" href="#the-retake" aria-label="Permalink to &quot;The retake&quot;">​</a></h3><p>For a block under 10/20, a Lead Trainer of your cohort or the Coordinator can open a <strong>retake</strong>:</p><ul><li>at most <strong>2 retakes</strong> per block (3 attempts in all);</li><li><strong>at least 15 days</strong> after your last grade on that block;</li><li>it is filled with the first grade given in Sève after it opens, and can be cancelled as long as it has not been graded.</li></ul><h2 id="the-tutored-project-the-defence-and-the-internship" tabindex="-1">The tutored project, the defence and the internship <a class="header-anchor" href="#the-tutored-project-the-defence-and-the-internship" aria-label="Permalink to &quot;The tutored project, the defence and the internship&quot;">​</a></h2><p>Besides the blocks, the Coordinator records the <strong>jury&#39;s</strong> decisions:</p><ul><li>the <strong>tutored project</strong>: its subject, whether it is validated, its grade;</li><li>the <strong>defence</strong>: its date, whether it is validated, its grade;</li><li>the <strong>internship</strong>: the company, and whether the internship is validated.</li></ul><p>Jury grades stay <strong>outside the average</strong>. A validated defence is a condition of the certificate; the internship does not block the certificate. When the jury has decided on every defence, a <strong>report</strong> (<code>PVS-NB-YYYY-XXX</code>) is produced, numbered and sealed.</p><h2 id="the-internship-agreement" tabindex="-1">The internship agreement <a class="header-anchor" href="#the-internship-agreement" aria-label="Permalink to &quot;The internship agreement&quot;">​</a></h2><p>If your training includes an internship, the Coordinator enters the information in Kura: the host company and its signing contact, the cohort Coach-Tutor who supervises the internship, the dates and the mission. They then send the <strong>internship agreement</strong> to sign. As long as nobody has signed, they can edit it; an edit cancels the sending.</p><ul><li><strong>You</strong>, an adult learner, sign it in your account with a code received by e-mail. A minor goes through their legal guardian, with a link valid for 7 days.</li><li><strong>The company</strong> signs through a link valid for 7 days and a code, without an account.</li><li>edPage group then counter-signs. The sealed PDF (<code>CONVS-NB-YYYY-XXX</code>) is sent to you, to the Coach-Tutor, to the company and to your legal guardian if there is one.</li></ul><p>The internship is part of the training and gives rise to no employment contract.</p><h2 id="your-tracking-documents" tabindex="-1">Your tracking documents <a class="header-anchor" href="#your-tracking-documents" aria-label="Permalink to &quot;Your tracking documents&quot;">​</a></h2><p>Everything produced for you (booklet, invoices, agreements, transcript of competencies) is in <strong>My documents</strong>.</p>',27)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
